                if (hasBrand) ebitda4 += 0.4; // sustained brand premium on revenue
                ds.ebitda = Math.round(ebitda4 * 10) / 10;
                if (ds.pikActive) {
                    ds.pikBalance = Math.round((ds.pikBalance + (ds.mezzPrincipal + ds.pikBalance) * this.MEZZ_RATE / 100) * 10) / 10;
                }
                ds.seniorDebt = Math.round((ds.seniorDebt - ds.annualSeniorAmort) * 10) / 10;
                if (ds.seniorDebt < 0) ds.seniorDebt = 0;
                ds.netDebt = Math.round((ds.seniorDebt + ds.mezzPrincipal + ds.pikBalance) * 10) / 10;
                if (this._roll(ds, 'r4_freeze', 0.25)) {
                    ds.freezeEvent = true;
                    eventLog += '❄️ ' + window.mySimulation.t('event_market_freeze') + '<br>';
                }
                if (this._roll(ds, 'r4_bid', 0.2)) {
                    ds.competingBid = true;
                    eventLog += '🔥 ' + window.mySimulation.t('event_competing_bid') + '<br>';
                }
                var exitMultiple = 0;
                var marsBonus = ds.marsEvent ? 0.5 : 0;
                var bidBonus = ds.competingBid ? 0.5 : 0;
                var brandBonus = hasBrand ? 0.85 : 0; // premium branded platform commands a higher multiple (EQIL B2)
                if (d.exitPath === 'strategic') {
                    exitMultiple = (ds.addonCompleted ? 11.5 : 10.5) + marsBonus + bidBonus + brandBonus;
                } else if (d.exitPath === 'secondary') {
                    exitMultiple = (ds.addonCompleted ? 10.0 : 9.5) + bidBonus * 0.5 + brandBonus * 0.5;
                } else if (d.exitPath === 'ipo') {
                    if (ds.freezeEvent) {
                        exitMultiple = (ds.addonCompleted ? 9.0 : 8.5) + brandBonus * 0.5;
                        eventLog += '⚠️ ' + window.mySimulation.t('ipo_forced_secondary') + '<br>';
                    } else {
                        exitMultiple = (ds.addonCompleted ? 10.5 : 10.0) + marsBonus * 0.3 + brandBonus;
                    }
                }
                // PIK leaves a mark: a distressed cap structure dents the exit multiple.
                if (ds.pikActive) exitMultiple -= 0.3;
                if (d.earnout === 'include') exitMultiple += 0.5;
                else if (d.earnout === 'partial') exitMultiple += 0.25;
                ds.exitMultiple = Math.round(exitMultiple * 100) / 100;
                ds.exitEV = Math.round(ds.ebitda * exitMultiple * 10) / 10;
                ds.exitEquity = Math.round((ds.exitEV - ds.netDebt) * 10) / 10;
                var totalEquity = ds.entryEquity + ds.additionalEquity;
                var fundShare = 1 - ds.mgmtIncentive / 100;
                var fundEquity = ds.exitEquity * fundShare;
                ds.moic = Math.round(fundEquity / totalEquity * 10) / 10;
                ds.irr = Math.round((Math.pow(Math.max(ds.moic, 0.01), 0.25) - 1) * 100 * 10) / 10;
                ds.leverageRatio = ds.ebitda > 0 ? Math.round(ds.netDebt / ds.ebitda * 10) / 10 : 0;
                var cashInt4 = this._cashInterest(ds, seniorBegin4);
                ds.coverageRatio = cashInt4 > 0 ? Math.round(ds.ebitda / cashInt4 * 10) / 10 : 99;
                ds.covenantStatus = (ds.coverageRatio < 2.0 || ds.leverageRatio > 5.5) ? 'breached' : 'ok';

                // PE value bridge (EQIL I1) — decompose equity value creation.
                var gEbitda = Math.round((ds.ebitda - this.ENTRY_EBITDA) * this.ENTRY_MULTIPLE * 10) / 10;
                var gMultiple = Math.round((exitMultiple - this.ENTRY_MULTIPLE) * ds.ebitda * 10) / 10;
                var gDebt = Math.round((ds.entryNetDebt - ds.netDebt) * 10) / 10;
                ds.valueBridge = {
                    entryEquity: ds.entryEquity,
                    ebitdaGrowth: gEbitda,
                    multipleExpansion: gMultiple,
                    debtPaydown: gDebt,
                    exitEquityGross: ds.exitEquity,
                    investedEquity: Math.round(totalEquity * 10) / 10
                };
                ds.peScore = this._peScore(ds);
                eventLog += this._bridgeHtml(ds);
            }

            // Idempotent history (write at index, never duplicate on replay).
            ds.ebitdaHistory[period - 1] = ds.ebitda;
            ds.leverageHistory[period - 1] = ds.leverageRatio;
            ds.moicHistory[period - 1] = ds.moic;
            ds.eventLog = eventLog;

            ds.periodApplied[period] = true;

            // running approximation of _peScore (which only runs on exit, period 4): same weights
            // and MOIC, covenant, growth and addon terms, with IRR annualized over the elapsed hold
            // years instead of the fixed 4-year exit hold; at period 4 the hold years match and this
            // reduces to the exact final peScore, scaled from 0-1000 down to 0-100
            var clampX = function(x) { return Math.max(0, Math.min(1, x)); };
            var holdYearsX = Math.max(1, period);
            var irrRunningX = Math.round((Math.pow(Math.max(ds.moic, 0.01), 1 / holdYearsX) - 1) * 1000) / 10;
            var sMoicX = clampX(ds.moic / 4.5) * 35;
            var sIrrX = clampX(irrRunningX / 40) * 25;
            var covScoreX = ds.covenantR2Outcome === 'ok' ? 20 : (ds.covenantR2Outcome === 'cured' ? 13 : (ds.covenantR2Outcome === 'waived' ? 7 : 3));
            var sGrowthX = clampX((ds.ebitda / this.ENTRY_EBITDA) / 1.6) * 15;
            var sExitX = ds.addonCompleted ? 5 : 3;
            var overallScoreX = Math.max(0, Math.min(100, Math.round(sMoicX + sIrrX + covScoreX + sGrowthX + sExitX)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScoreX });

            var result = {
                period: period,
                ebitda: ds.ebitda,
                netDebt: ds.netDebt,
                leverage: ds.leverageRatio,
                coverage: ds.coverageRatio,
                moic: ds.moic,
                irr: ds.irr,
                exitEquity: ds.exitEquity,
                covenantStatus: ds.covenantStatus,
                covenantOutcome: ds.covenantR2Outcome,
                peScore: ds.peScore,
                eventLog: eventLog
            };
            ds.periodResults[period] = result;

            this._renderEvents(ds);
            this._paintCovenant(ds);

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext, domainState: ds });
            })(state.currentPeriod + 1), 500);

            return result;
        }

        _peScore(ds) {
            // Weighted "PE Excellence Score" 0-1000 (EQIL I2), per concept §7 weights.
            var clamp = function(x) { return Math.max(0, Math.min(1, x)); };
            var sMoic = clamp(ds.moic / 4.5) * 35;
            var sIrr = clamp(ds.irr / 40) * 25;
            var covScore = ds.covenantR2Outcome === 'ok' ? 20 : (ds.covenantR2Outcome === 'cured' ? 13 : (ds.covenantR2Outcome === 'waived' ? 7 : 3));
            var sGrowth = clamp((ds.ebitda / this.ENTRY_EBITDA) / 1.6) * 15;
            var sExit = ds.addonCompleted ? 5 : 3;
            return Math.round((sMoic + sIrr + covScore + sGrowth + sExit) * 10);
        }

        _bridgeHtml(ds) {
            var b = ds.valueBridge;
            if (!b) return '';
            var t = function(k) { return window.mySimulation.t(k); };
            var row = function(label, val, cls) {
                var sign = val > 0 ? '+' : '';
                return '<div class="lbo-bridge-row"><span>' + label + '</span><span class="' + (cls || '') + '">' + sign + 'USD ' + val.toFixed(1) + 'M</span></div>';
            };
            return '<div class="lbo-bridge"><div class="lbo-bridge-title">' + t('bridge_heading') + '</div>' +
                row(t('bridge_entry_equity'), b.entryEquity, '') +
                row(t('bridge_ebitda_growth'), b.ebitdaGrowth, 'pos') +
                row(t('bridge_multiple_expansion'), b.multipleExpansion, b.multipleExpansion >= 0 ? 'pos' : 'neg') +
                row(t('bridge_debt_paydown'), b.debtPaydown, b.debtPaydown >= 0 ? 'pos' : 'neg') +
                '<div class="lbo-bridge-row lbo-bridge-total"><span>' + t('bridge_exit_equity') + '</span><span>USD ' + b.exitEquityGross.toFixed(1) + 'M</span></div>' +
                '<div class="lbo-bridge-score">' + t('score_label') + ': <strong>' + ds.peScore + ' / 1000</strong></div>' +
                '<div class="lbo-bridge-row" style="margin-top:8px"><span>' + t('bridge_covenant') + '</span><span class="' + (ds.covenantR2Outcome === 'ok' ? 'pos' : (ds.covenantR2Outcome === 'cured' ? '' : 'neg')) + '">' + t('cov_outcome_' + ds.covenantR2Outcome) + '</span></div>' +
                '<div class="lbo-bridge-note">' + t('bridge_note') + '</div></div>';
        }

        _renderEvents(ds) {
            var el = document.getElementById('eventLogDisplay');
            if (el) el.innerHTML = ds.eventLog || '';
            var ep = document.getElementById('eventLogPanel');
            if (ep) ep.style.display = ds.eventLog ? 'block' : 'none';
        }

        _paintCovenant(ds) {
            var card = document.getElementById('coverageCard');
            var lev = document.getElementById('leverageCard');
            var cls = 'lbo-sim-status-card';
            var covOk = ds.coverageRatio >= 2.0;
            var levOk = ds.leverageRatio <= 5.5;
            if (card) card.className = cls + (covOk ? ' cov-ok' : ' cov-bad');
            if (lev) lev.className = cls + (levOk ? ' cov-ok' : ' cov-bad');
            var badge = document.getElementById('covenantBadge');
            if (badge) {
                var map = { ok: 'covenant_ok', cured: 'covenant_cured', waived: 'covenant_waived', breached: 'covenant_breached_badge' };
                badge.textContent = window.mySimulation.t(map[ds.covenantStatus] || 'covenant_ok');
                badge.className = 'lbo-covenant-badge ' + (ds.covenantStatus === 'ok' ? 'ok' : (ds.covenantStatus === 'cured' ? 'warn' : 'bad'));
                badge.style.display = 'inline-block';
            }
        }

