        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var i = 0; i < panels.length; i++) {
                var p = document.getElementById(panels[i]);
                if (p) p.style.display = (i === period - 1) ? 'block' : 'none';
            }
            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation) {
                var key = 'briefing_r' + Math.min(period, 4);
                briefEl.innerHTML = window.mySimulation.t(key);
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new LBOAdapter(), {
            simulationType: 'lbo_pe_simulation',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
